import 'dart:convert';
import 'dart:io';
import 'apply_panjika_print.dart' as previous;
void main(List<String> args) {
  if (args.length != 1) throw ArgumentError('Expected candidate main.dart');
  final file = File(args.single);
  final initial = file.readAsStringSync();
  final initialStart = initial.indexOf('class _BengaliCalendarScreenState');
  final initialEnd = initial.indexOf('class _MonthlyPanjikaSlider', initialStart);
  if (initialStart < 0 || initialEnd < initialStart) throw StateError('Calendar missing');
  if (!initial.substring(initialStart, initialEnd).contains('mainAxisExtent: 112 * _tsFactor(context)')) {
    previous.main(args);
  }
  var source = file.readAsStringSync();
  final a = source.indexOf('class _CalendarDayCellState extends State<_CalendarDayCell>');
  final b = source.indexOf('class ReminderItem {', a);
  if (a < 0 || b < a) throw StateError('Calendar cell missing');
  final cell = utf8.decode(base64Decode('')).replaceAll('\n', '\r\n');
  source = source.replaceRange(a, b, cell);
  const heading = "'বাংলা পঞ্জিকা'";
  final stateStart = source.indexOf('class _BengaliCalendarScreenState');
  final stateEnd = source.indexOf('class _MonthlyPanjikaSlider', stateStart);
  var page = source.substring(stateStart, stateEnd);
  page = page.replaceAll('mainAxisExtent: 112 * _tsFactor(context)',
      'mainAxisExtent: 148 * _tsFactor(context)');
  page = page.replaceAll(heading, "'শ্রীপঞ্চাঙ্গ • বাংলা পঞ্জিকা'");
  page = page.replaceAll('fontSize: 23,', 'fontSize: 28,');
  page = page.replaceAll('0xFFFF9A3E', '0xFF99551B')
      .replaceAll('0xFF2FBFA3', '0xFF236C57').replaceAll('0xFFA285E8', '0xFF714395');
  page = page.replaceAll('                  // ---- ট্যাব বার (ফিল্টার) ----',
    "                  const Padding(padding: EdgeInsets.symmetric(vertical: 10),\r\n"
    "                    child: Text('তিথি • নক্ষত্র • ব্রত • পার্বণ', textAlign: TextAlign.center,\r\n"
    "                      style: TextStyle(color: Color(0xFFA52222), fontSize: 15, fontWeight: FontWeight.w700))),\r\n"
    '                  // ---- ট্যাব বার (ফিল্টার) ----');
  source = source.replaceRange(stateStart, stateEnd, page);
  file.writeAsStringSync(source);
  stdout.writeln('Distinct panjika layout and separated date cells applied.');
}
